INSERT INTO wf_definition(id,create_by,create_time,flow_code,flow_name,version,status,description,entry_node_key,config_json) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,'EDU_GRADEBOOK_REVIEW','成绩册审核','v1','PUBLISHED','成绩册第一片独立审核流程：教研审核后教务审核','RESEARCH_REVIEW','{"approvalMode":"SINGLE","allowReturn":true}' WHERE NOT EXISTS(SELECT 1 FROM wf_definition WHERE flow_code='EDU_GRADEBOOK_REVIEW' AND version='v1');
INSERT INTO wf_node(id,create_by,create_time,flow_id,node_key,node_name,node_type,executor,properties_json) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'RESEARCH_REVIEW','教研审核','APPROVAL','ROLE:EDU_GRADE_REVIEWER','{"approvalMode":"SINGLE","allowReturn":true}' FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_node n WHERE n.flow_id=d.id AND n.node_key='RESEARCH_REVIEW');
INSERT INTO wf_node(id,create_by,create_time,flow_id,node_key,node_name,node_type,executor,properties_json) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'ACADEMIC_APPROVAL','教务审核','APPROVAL','ROLE:EDU_ACADEMIC_APPROVER','{"approvalMode":"SINGLE","allowReturn":true}' FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_node n WHERE n.flow_id=d.id AND n.node_key='ACADEMIC_APPROVAL');
INSERT INTO wf_node(id,create_by,create_time,flow_id,node_key,node_name,node_type,properties_json) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'START','开始','START','{}' FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_node n WHERE n.flow_id=d.id AND n.node_key='START');
INSERT INTO wf_node(id,create_by,create_time,flow_id,node_key,node_name,node_type,properties_json) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'END','结束','END','{}' FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_node n WHERE n.flow_id=d.id AND n.node_key='END');
INSERT INTO wf_edge(id,create_by,create_time,flow_id,from_node_key,to_node_key,is_default) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'START','RESEARCH_REVIEW',true FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_edge e WHERE e.flow_id=d.id AND e.from_node_key='START');
INSERT INTO wf_edge(id,create_by,create_time,flow_id,from_node_key,to_node_key,is_default) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'RESEARCH_REVIEW','ACADEMIC_APPROVAL',true FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_edge e WHERE e.flow_id=d.id AND e.from_node_key='RESEARCH_REVIEW');
INSERT INTO wf_edge(id,create_by,create_time,flow_id,from_node_key,to_node_key,is_default) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,d.id,'ACADEMIC_APPROVAL','END',true FROM wf_definition d WHERE d.flow_code='EDU_GRADEBOOK_REVIEW' AND d.version='v1' AND NOT EXISTS(SELECT 1 FROM wf_edge e WHERE e.flow_id=d.id AND e.from_node_key='ACADEMIC_APPROVAL');
